import sys
import heapq

class Edge:
    __slots__ = ('src', 'dst', 'cap', 'cost', 'rev')
    def __init__(self, src, dst, cap, cost, rev):
        self.src = src
        self.dst = dst
        self.cap = cap
        self.cost = cost
        self.rev = rev

class MinCostFlow:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]
        self.supp = [0] * n
        self.ptnl = [0] * n
        self.min_cost = 0
        self.total_cost = 0
        self._first = True  # for initial Bellman-Ford

    def size(self):
        return self.n

    def add_edge(self, src, dst, cap, cost):
        if cap <= 0:
            return
        if cost < 0:
            self.supp[src] -= cap
            self.supp[dst] += cap
            self.min_cost += cap * cost
            self.total_cost -= cap * cost
            self.adj[dst].append(Edge(dst, src, cap, -cost, len(self.adj[src])))
            self.adj[src].append(Edge(src, dst, 0, cost, len(self.adj[dst]) - 1))
        else:
            self.total_cost += cap * cost
            self.adj[src].append(Edge(src, dst, cap, cost, len(self.adj[dst])))
            self.adj[dst].append(Edge(dst, src, 0, -cost, len(self.adj[src]) - 1))

    def supply(self, node, vol):
        self.supp[node] += vol

    def flow(self):
        infty = self.total_cost + 1

        # Initial potentials using Bellman-Ford (only once)
        if self._first:
            self._first = False
            dist = [infty] * self.n
            dist[0] = 0
            for _ in range(self.n):
                updated = False
                for v in range(self.n):
                    if dist[v] == infty:
                        continue
                    for e in self.adj[v]:
                        if e.cap > 0 and dist[e.dst] > dist[v] + e.cost:
                            dist[e.dst] = dist[v] + e.cost
                            updated = True
                if not updated:
                    break
            for v in range(self.n):
                if dist[v] < infty:
                    self.ptnl[v] = dist[v]

        aug = True
        while aug:
            aug = False
            last = [self.n] * self.n
            dist = [infty] * self.n
            pq = []
            for node in range(self.n):
                if self.supp[node] > 0:
                    dist[node] = 0
                    heapq.heappush(pq, (0, node))

            while pq:
                d, node = heapq.heappop(pq)
                if d != dist[node]:
                    continue
                self.ptnl[node] -= d
                if self.ptnl[node] > infty:
                    self.ptnl[node] = infty
                dist[node] = infty
                for i, e in enumerate(self.adj[node]):
                    if e.cap == 0:
                        continue
                    nd = self.ptnl[node] + e.cost - self.ptnl[e.dst]
                    if nd < dist[e.dst]:
                        dist[e.dst] = nd
                        last[e.dst] = i
                        heapq.heappush(pq, (nd, e.dst))

            shut = [False] * self.n
            for dst in range(self.n):
                if self.supp[dst] < 0 and last[dst] != self.n:
                    resid = -self.supp[dst]
                    src = dst
                    block = self.n
                    while last[src] != self.n and not shut[src]:
                        e = self.adj[src][last[src]]
                        if resid >= e.cap:
                            resid = e.cap
                            block = src
                        src = e.src
                    if shut[src]:
                        block = src
                    else:
                        if resid >= self.supp[src]:
                            resid = self.supp[src]
                            block = src
                        node = dst
                        while node != src:
                            e = self.adj[node][last[node]]
                            e.cap -= resid
                            self.adj[e.dst][e.rev].cap += resid
                            node = e.src
                        self.supp[src] -= resid
                        self.supp[dst] += resid
                        self.min_cost += self.ptnl[dst] * resid
                        aug = True
                    if block != self.n:
                        node = dst
                        while node != block:
                            shut[node] = True
                            node = self.adj[node][last[node]].src
                        shut[block] = True

        for s in self.supp:
            if s > 0:
                return False
        return True

    def optimal(self):
        return self.min_cost if self.flow() else -1

def main():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))
    c = int(next(it))
    d = int(next(it))
    tlim = 105
    mcf = MinCostFlow(6100)
    for _ in range(k):
        j = int(next(it)) - 1
        mcf.supply(j, 1)
    for _ in range(m):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        for t in range(tlim):
            nu = u + n
            nv = v + n
            for x in range(k):
                cost = c + d * (x * 2 + 1)
                mcf.add_edge(u, nv, 1, cost)
                mcf.add_edge(v, nu, 1, cost)
            u = nu
            v = nv
    for i in range(1, n):
        for t in range(tlim):
            mcf.add_edge(n * t + i, n * (t + 1) + i, k, c)
    dst = mcf.size() - 1
    mcf.supply(dst, -k)
    for t in range(tlim + 1):
        mcf.add_edge(t * n, dst, k, 0)
    print(mcf.optimal())

if __name__ == "__main__":
    main()
